actions.script:
import java.sql.Timestamp
Calendar cal = Calendar.getInstance()
cal.add(Calendar.DAY_OF_YEAR, 90)
Timestamp thresholdDate = new Timestamp(cal.getTimeInMillis())

// Org isolation (explicit — Asset isn't in the active-org entity-filter set).
def assetFind = ec.entity.find("mantle.product.asset.Asset")
    .condition("expiryDate", org.moqui.entity.EntityCondition.LESS_THAN_EQUAL_TO, thresholdDate)
    .condition("quantityOnHandTotal", org.moqui.entity.EntityCondition.GREATER_THAN, BigDecimal.ZERO)
if (organizationPartyId && organizationPartyId != '_NA_') assetFind.condition("ownerPartyId", organizationPartyId)
def assetList = assetFind.list()

// ZE-INV-011 (IV-111): batch-load products + suppliers up front to avoid an N+1 (was one Product
// query per asset + per-order supplier queries, so the page slowed in proportion to the number
// of expiring lots). Now 3 set-based lookups regardless of asset count.
def _pids = assetList.collect { it.productId }.findAll { it }.unique()
def _prodMap = [:]
if (_pids) ec.entity.find("mantle.product.Product").condition("productId", "in", _pids).list().each { _prodMap[it.productId] = it }

def _oids = assetList.collect { it.acquireOrderId }.findAll { it }.unique()
def _orderVendor = [:]
if (_oids) ec.entity.find("mantle.order.OrderPart").condition("orderId", "in", _oids).disableAuthz().list().each {
    if (it.vendorPartyId && !_orderVendor.containsKey(it.orderId)) _orderVendor[it.orderId] = it.vendorPartyId
}
def _vids = _orderVendor.values().findAll { it }.unique()
def _vendorName = [:]
if (_vids) ec.entity.find("mantle.party.PartyDetail").condition("partyId", "in", _vids).disableAuthz().list().each {
    _vendorName[it.partyId] = it.organizationName ?: ((it.firstName ?: '') + ' ' + (it.lastName ?: '')).trim()
}

def _nowMs = ec.user.nowTimestamp.getTime()
List expList = []
for (def asset : assetList) {
    def product = _prodMap[asset.productId]
    if (product == null) { continue }
    // supplier for PO-received lots (acquireOrderId -> OrderPart.vendorPartyId -> party name)
    def _vid = asset.acquireOrderId ? _orderVendor[asset.acquireOrderId] : null
    def supplierName = _vid ? (_vendorName[_vid] ?: '') : ''
    // value at cost (valuationRate) -> acquireCost -> MRP; tag the basis
    def _pos = { v -> (v != null && (v as BigDecimal).signum() > 0) ? (v as BigDecimal) : null }
    def valRate = _pos(asset.valuationRate) ?: _pos(asset.acquireCost)
    def valBasis = (valRate != null) ? 'cost' : null
    if (valRate == null) { valRate = _pos(asset.mrpAmount); if (valRate != null) valBasis = 'MRP' }
    if (valRate == null) { valRate = BigDecimal.ZERO; valBasis = 'unvalued' }
    def qoh = asset.quantityOnHandTotal ?: BigDecimal.ZERO
    def _days = asset.expiryDate ? (int)((asset.expiryDate.getTime() - _nowMs) / 86400000L) : 999
    expList.add([
        assetId: asset.assetId, productName: product?.productName ?: 'Unknown', supplierName: supplierName,
        expiryDate: asset.expiryDate, daysToExpiry: _days, quantity: qoh,
        value: valRate.multiply(qoh), valuationRate: valRate, valueBasis: valBasis,
        batchNumber: asset.batchNumber ?: 'N/A'
    ])
}

// search + within-days filter
def _search = (searchText ?: '').toString().trim().toLowerCase()
def _within = (withinDays ?: '').toString().trim()
if (_search) expList = expList.findAll { r ->
    (((r.productName ?: '') + ' ' + (r.assetId ?: '') + ' ' + (r.batchNumber ?: '') + ' ' + (r.supplierName ?: '')).toLowerCase().contains(_search) )
}
if (_within) expList = expList.findAll { r -> (_within == 'expired') ? (r.daysToExpiry <= 0) : (r.daysToExpiry <= (_within as Integer)) }

BigDecimal totalVal = BigDecimal.ZERO
for (def r : expList) { totalVal = totalVal.add(r.value ?: BigDecimal.ZERO) }

// sort (leading '-' = desc, whitelist, nulls last)
def _ob = (orderByField ?: 'expiryDate').toString()
def _desc = _ob.startsWith('-'); def _fld = _desc ? _ob.substring(1) : _ob
if (!(_fld in ['assetId','productName','batchNumber','supplierName','expiryDate','quantity','value'])) _fld = 'expiryDate'
def _nc = { a, b -> (a == null && b == null) ? 0 : (a == null ? 1 : (b == null ? -1 : (a <=> b))) }
expList.sort { x, y -> def c = _nc(x[_fld], y[_fld]); _desc ? -c : c }

totalExpiryValue = totalVal
expiringAssets = expList

String fromGstin = fromFac?.taxRegistrationNumber
String toGstin = toFac?.taxRegistrationNumber
String igstInvoiceIdOut = null

// If they have different GSTINs, it's an inter-state transfer, treated as a sale requiring IGST
if (fromGstin && toGstin && fromGstin != toGstin) {
    // Create IGST Invoice
    def invoiceOut = ec.service.sync().name("create#mantle.account.invoice.Invoice")
        .parameters([
            invoiceTypeEnumId: 'InvoiceSales',
            statusId: 'InvoiceInProcess',
            fromPartyId: organizationPartyId,
            toPartyId: organizationPartyId,
            invoiceDate: ec.user.nowTimestamp,
            description: 'IGST Invoice for Branch Transfer'
        ]).call()
    igstInvoiceIdOut = invoiceOut.invoiceId
}

// Determine totalValue placeholder logic
BigDecimal val = totalValue ?: BigDecimal.ZERO
String ewayRequired = (val > new BigDecimal("50000")) ? "Y" : "N"

// Create the StockTransfer
def result = ec.service.sync().name("create#zenith.erp.inventory.StockTransfer")
    .parameters(context + [statusId: 'StxDraft', igstInvoiceId: igstInvoiceIdOut, ewayBillRequired: ewayRequired])
    .call()
stockTransferId = result.stockTransferId

serIds = (serialNumbers instanceof List) ? serialNumbers : (serialNumbers ? [serialNumbers] : [])
serIds = serIds.findAll { it }
validSerials = []
for (sid in serIds) {
    def sn = ec.entity.find("zenith.erp.inventory.ProductSerialNumber").condition("serialNumberId", sid).one()
    if (sn == null || sn.productId != productId || sn.statusId != 'SnInStock'
        || (stx?.fromFacilityId && sn.facilityId != stx.fromFacilityId)) {
        ec.message.addError("Serial " + (sn?.serialNumber ?: sid) + " isn't an in-stock unit of this product at the sending facility.")
    } else { validSerials.add(sn) }
}

def org = stx.organizationPartyId ?: ec.user.getPreference('ACTIVE_ORGANIZATION')
def shipItems = ec.entity.find("zenith.erp.inventory.StockTransferItem").condition("stockTransferId", stockTransferId).list()

// Validate every line before moving anything (don't partially ship).
//  - Batch-tracked product: a line moves from ONE source batch (its own batch, else the
//    earliest-expiry batch) so the batch identity + expiry can follow the goods (Receive
//    recreates it at the destination). If that batch can't cover the qty, block with a
//    clear message rather than silently losing traceability.
//  - Other tracked products: just check the source facility on-hand (no negative stock).
//  - Untracked products (non-tracking tenants, on-hand 0): no guard.
def picks = [:]  // transferItemSeqId -> chosen source batch Asset
for (li in shipItems) {
    if (!li.productId || !li.quantity) continue
    def prod = ec.entity.find("mantle.product.Product").condition("productId", li.productId).one()
    def qty = li.quantity as BigDecimal
    if (prod?.enableBatchTracking == 'Y') {
        def bf = ec.entity.find("mantle.product.asset.Asset")
            .condition("ownerPartyId", org).condition("productId", li.productId)
            .condition("facilityId", stx.fromFacilityId)
            .condition("quantityOnHandTotal", org.moqui.entity.EntityCondition.GREATER_THAN, BigDecimal.ZERO)
        if (li.batchNumber) bf.condition("batchNumber", li.batchNumber)
        def batches = bf.orderBy("expiryDate,receivedDate,assetId").list()
        if (!batches) { ec.message.addError("No stock of " + li.productId + " at the source facility to ship."); continue }
        def picked = batches[0]
        if (qty.compareTo((picked.quantityOnHandTotal ?: 0) as BigDecimal) > 0) {
            ec.message.addError("Batch " + (picked.batchNumber ?: '(unnamed)') + " of " + li.productId + " has only " + picked.quantityOnHandTotal + " at the source; choose a batch with enough stock or split this transfer line."); continue
        }
        picks[li.transferItemSeqId] = picked
    } else if (prod?.inventoryTracked == 'Y') {
        def srcAssets = ec.entity.find("mantle.product.asset.Asset")
            .condition("ownerPartyId", org).condition("productId", li.productId)
            .condition("facilityId", stx.fromFacilityId).list()
        def srcQoh = srcAssets ? (srcAssets.sum { it.quantityOnHandTotal ?: 0 } as BigDecimal) : BigDecimal.ZERO
        if (qty.compareTo(srcQoh) > 0) {
            ec.message.addError("Not enough stock to ship product " + li.productId + " from the source facility: have " + srcQoh + ", need " + li.quantity + ".")
        }
    }
}
if (ec.message.hasError()) return

// All lines valid — move stock out of the source.
ec.service.sync().name("update#zenith.erp.inventory.StockTransfer")
    .parameters([stockTransferId: stockTransferId, statusId: 'StxInTransit']).call()
for (li in shipItems) {
    if (!li.productId || !li.quantity) continue
    def qty = li.quantity as BigDecimal
    def picked = picks[li.transferItemSeqId]
    if (picked != null) {
        // Deplete the SPECIFIC source batch (via the batch-aware stock service) and stamp the
        // batch on the line so Receive can recreate it at the destination with its expiry.
        ec.service.sync().name("zenith.inventory.InventoryStockServices.adjust#AssetOnHand")
            .parameters([organizationPartyId:org, productId:li.productId, facilityId:stx.fromFacilityId,
                         batchNumber:picked.batchNumber, quantityDiff:(-qty), reason:("Transfer out " + stockTransferId)]).call()
        ec.service.sync().name("update#zenith.erp.inventory.StockTransferItem").parameters([
            stockTransferId:stockTransferId, transferItemSeqId:li.transferItemSeqId,
            batchNumber:picked.batchNumber, fromAssetId:picked.assetId]).call()
    } else {
        ec.service.sync().name("zenith.inventory.InventoryStockServices.adjust#AssetOnHand")
            .parameters([organizationPartyId:org, productId:li.productId, facilityId:stx.fromFacilityId,
                         quantityDiff:(-qty), reason:("Transfer out " + stockTransferId)]).call()
    }
}

// Update status
ec.service.sync().name("update#zenith.erp.inventory.StockTransfer")
    .parameters([stockTransferId: stockTransferId, statusId: 'StxReceived']).call()
// Add the received stock to the DESTINATION facility (per line)
def org = stx.organizationPartyId ?: ec.user.getPreference('ACTIVE_ORGANIZATION')
def recItems = ec.entity.find("zenith.erp.inventory.StockTransferItem").condition("stockTransferId", stockTransferId).list()
for (li in recItems) {
    def qr = (li.quantityReceived != null) ? li.quantityReceived : li.quantity
    if (!li.productId || !qr) continue
    qr = qr as BigDecimal
    def prod = ec.entity.find("mantle.product.Product").condition("productId", li.productId).one()

    if (prod?.enableBatchTracking == 'Y' && li.fromAssetId) {
        // Carry the batch number + expiry/mfg/mrp to the destination facility (so Expiry Risk
        // stays accurate) instead of dropping it into a generic no-batch asset. The batch-aware
        // stock service finds-or-creates the destination batch asset and adds the qty.
        def src = ec.entity.find("mantle.product.asset.Asset").condition("assetId", li.fromAssetId).one()
        ec.service.sync().name("zenith.inventory.InventoryStockServices.adjust#AssetOnHand")
            .parameters([organizationPartyId:org, productId:li.productId, facilityId:stx.toFacilityId,
                         batchNumber:li.batchNumber, quantityDiff:qr, reason:("Transfer in " + stockTransferId),
                         expiryDate:src?.expiryDate, manufacturingDate:src?.manufacturingDate,
                         mrpAmount:src?.mrpAmount, valuationRate:src?.valuationRate]).call()
    } else {
        ec.service.sync().name("zenith.inventory.InventoryStockServices.adjust#AssetOnHand")
            .parameters([organizationPartyId:org, productId:li.productId, facilityId:stx.toFacilityId,
                         quantityDiff:qr, reason:("Transfer in " + stockTransferId)]).call()
    }

    // Serial-tracked: relocate the serials to the destination facility + audit row, so a
    // serial's recorded location follows the physical goods. Move the units the user PICKED
    // for this line if any; otherwise fall back to the first N in-stock serials at the source.
    if (prod?.enableSerialTracking == 'Y') {
        def picked = ec.entity.find("zenith.erp.inventory.StockTransferItemSerial")
            .condition("stockTransferId", stockTransferId).condition("transferItemSeqId", li.transferItemSeqId).list()
        def serials
        if (picked) {
            serials = picked.collect { ec.entity.find("zenith.erp.inventory.ProductSerialNumber").condition("serialNumberId", it.serialNumberId).one() }.findAll { it != null }
        } else {
            def moveN = qr.setScale(0, java.math.RoundingMode.DOWN).intValue()
            serials = moveN > 0 ? ec.entity.find("zenith.erp.inventory.ProductSerialNumber")
                .condition("productId", li.productId).condition("facilityId", stx.fromFacilityId)
                .condition("statusId", "SnInStock").orderBy("receivedDate,serialNumberId").limit(moveN).list() : []
        }
        for (sn in serials) {
            if (sn == null) continue
            ec.service.sync().name("update#zenith.erp.inventory.ProductSerialNumber")
                .parameters([serialNumberId:sn.serialNumberId, facilityId:stx.toFacilityId]).call()
            ec.service.sync().name("create#zenith.erp.inventory.SerialNumberHistory").parameters([
                serialNumberId:sn.serialNumberId, eventDate:ec.user.nowTimestamp, eventType:'Transfer',
                fromFacilityId:stx.fromFacilityId, toFacilityId:stx.toFacilityId,
                referenceType:'StockTransfer', referenceId:stockTransferId, performedByUserId:ec.user.userId,
                notes:('Relocated by stock transfer ' + stockTransferId)]).call()
        }
    }

    if (li.quantityReceived == null) {
        ec.service.sync().name("update#zenith.erp.inventory.StockTransferItem")
            .parameters([stockTransferId:stockTransferId, transferItemSeqId:li.transferItemSeqId, quantityReceived:li.quantity]).call()
    }
}

def fromFac = ec.entity.find("mantle.facility.Facility").condition("facilityId", newFrom).one()
def toFac = ec.entity.find("mantle.facility.Facility").condition("facilityId", newTo).one()
def interState = (fromFac?.taxRegistrationNumber && toFac?.taxRegistrationNumber
                  && fromFac.taxRegistrationNumber != toFac.taxRegistrationNumber)
if (interState && !stx.igstInvoiceId) {
    def inv = ec.service.sync().name("create#mantle.account.invoice.Invoice").parameters([
        invoiceTypeEnumId:'InvoiceSales', statusId:'InvoiceInProcess',
        fromPartyId:stx.organizationPartyId, toPartyId:stx.organizationPartyId,
        invoiceDate:ec.user.nowTimestamp, description:'IGST Invoice for Branch Transfer']).call()
    ec.service.sync().name("update#zenith.erp.inventory.StockTransfer")
        .parameters([stockTransferId:stockTransferId, igstInvoiceId:inv.invoiceId]).call()
} else if (!interState && stx.igstInvoiceId) {
    // now intra-state: void the placeholder invoice + detach it
    def inv = ec.entity.find("mantle.account.invoice.Invoice").condition("invoiceId", stx.igstInvoiceId).one()
    if (inv && inv.statusId != 'InvoiceCancelled') { inv.statusId = 'InvoiceCancelled'; inv.update() }
    def ev = ec.entity.find("zenith.erp.inventory.StockTransfer").condition("stockTransferId", stockTransferId).one()
    if (ev) { ev.igstInvoiceId = null; ev.update() }
}

if.script:
// placeholder IGST invoice (never finalized in the draft flow): void it rather than hard-delete
def inv = ec.entity.find("mantle.account.invoice.Invoice").condition("invoiceId", stx.igstInvoiceId).one()
if (inv && inv.statusId != 'InvoiceCancelled') { inv.statusId = 'InvoiceCancelled'; inv.update() }

actions.script:
def prod = ec.entity.find("mantle.product.Product").condition("productId", productId).one()
if (prod == null) { ec.message.addError("Product not found."); return }
def activeOrg = ec.user.getPreference('ACTIVE_ORGANIZATION')
if (!ec.user.isInGroup('ADMIN') && (!activeOrg || prod.ownerPartyId != activeOrg)) {
    ec.message.addError("Product not found for your account."); return
}
def refs = []
if (ec.entity.find("zenith.erp.pos.PosTransactionItem").condition("productId", productId).count() > 0) refs.add("POS bills")
if (ec.entity.find("mantle.account.invoice.InvoiceItem").condition("productId", productId).count() > 0) refs.add("invoices")
if (ec.entity.find("mantle.order.OrderItem").condition("productId", productId).count() > 0) refs.add("orders")
def assets = ec.entity.find("mantle.product.asset.Asset").condition("productId", productId).list()
def hasStock = false
for (a in assets) {
    if (((a.quantityOnHandTotal ?: 0) as BigDecimal) != 0) { hasStock = true; break }
    if (ec.entity.find("mantle.product.asset.AssetDetail").condition("assetId", a.assetId).count() > 0) { hasStock = true; break }
}
if (hasStock) refs.add("stock records")
if (refs) {
    ec.message.addError("Cannot delete: this product is on " + refs.join(", ") + " and must stay for history/audit.")
    return
}
// audit: an irreversible delete on a live system must be reconstructable from the logs
ec.logger.warn("delete#Product AUDIT: user " + (ec.user.username ?: "?") + " permanently deleting product " + productId + " (org " + prod.ownerPartyId + "): " + groovy.json.JsonOutput.toJson(new HashMap(prod)))
try {
    ec.entity.find("mantle.product.ProductPrice").condition("productId", productId).deleteAll()
    ec.entity.find("zenith.erp.pos.PosProductModePrice").condition("productId", productId).deleteAll()
    ec.entity.find("mantle.product.category.ProductCategoryMember").condition("productId", productId).deleteAll()
    ec.entity.find("mantle.product.ProductIdentification").condition("productId", productId).deleteAll()
    for (a in assets) { try { a.delete() } catch (Exception ignored) { } }
    ec.entity.find("mantle.product.Product").condition("productId", productId).deleteAll()
    ec.message.addMessage("Product deleted.")
} catch (Exception e) {
    ec.logger.warn("delete#Product blocked for " + productId + ": " + e.message)
    ec.message.addError("Cannot delete this product - it is referenced by other records (e.g. variants or stock).")
}
